script:
(function () {
  'use strict';
  // Repossession of real property under IRC 1038, following IRS Pub. 537 (2025), "Real Property",
  // Worksheets D and E.
  //   Gross profit = selling price - adjusted basis - selling expenses.
  //   Contract price = selling price - existing mortgage the buyer assumed + any part of that mortgage
  //   above (adjusted basis + selling expenses). Gross profit % = gross profit / contract price.
  //   Worksheet D: line 3 = payments received before repossession - gain already reported (not below 0);
  //   line 7 = gross profit - (gain already reported + repossession costs); taxable gain (line 8) =
  //   the lesser of lines 3 and 7, not below 0. The line 7 limit is skipped for an indefinite selling price.
  //   Worksheet E: basis in the obligation = unpaid balance - unpaid balance x gross profit %;
  //   basis in the repossessed property = that basis + taxable gain + repossession costs.
  //   A bad debt deduction taken in an earlier year is income in the repossession year and adds
  //   to the basis in the obligation. If the full gain was reported in the year of sale (installment
  //   method not used), gain already reported = gross profit and the obligation's basis is its unpaid
  //   balance; any taxable gain is ordinary income.
  // Verified (Node, scratchpad lkrepo/tests/repo.test.js) against Pub. 537's worked example (land sold
  //   for $25,000, basis $19,000, expenses $1,000; $9,000 received, $1,800 reported, $16,000 unpaid,
  //   $500 costs): gross profit $5,000 at 20%; line 3 $7,200, line 7 $2,700, taxable gain $2,700;
  //   unrealized profit $3,200, obligation basis $12,800, basis of repossessed land $16,000.
  //   Assumed-mortgage contract price: $25,000 sale, $12,000 assumed, basis $10,000 + $1,000 expenses
  //   -> contract price $14,000, gross profit % 100%. Blank or negative input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pctFmt = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function grossProfit(price, basis, exp, assumed) {
    var gp = price - basis - exp;
    var cp = price - assumed + Math.max(0, assumed - basis - exp);
    return { gp: gp, cp: cp, pct: gp > 0 && cp > 0 ? Math.min(1, gp / cp) : 0 };
  }

  function repossess(p) {
    var g = grossProfit(p.price, p.basis, p.exp, p.assumed);
    var full = p.method === 'full';
    var reported = full ? Math.max(0, g.gp) : p.reported;
    var pct = full ? 0 : g.pct;
    var d3 = Math.max(0, p.payments - reported);
    var d4 = Math.max(0, g.gp);
    var d6 = reported + p.costs;
    var d7 = d4 - d6;
    var d8 = p.indefinite ? d3 : Math.max(0, Math.min(d3, d7));
    var e3 = p.unpaid * pct;
    var e4 = p.unpaid - e3 + p.badDebt;
    var e7 = e4 + d8 + p.costs;
    return { g: g, full: full, reported: reported, pct: pct, d1: p.payments, d3: d3, d4: d4, d6: d6, d7: d7, d8: d8,
      e1: p.unpaid, e3: e3, e4: e4, e7: e7, expected: g.pct * p.payments };
  }

  var IDS = ['rrpTaxable', 'rrpNewBasis', 'rrpGp', 'rrpGpPct', 'rrpNote', 'rrpExpected', 'rrpBadDebtIncome', 'rrpContract'];

  function rows(id, lines) {
    el(id).innerHTML = lines.map(function (l) {
      return '<tr><td>' + l[0] + '</td><td>' + l[1] + '</td><td>' + l[2] + '</td></tr>';
    }).join('');
  }

  function update() {
    var method = el('rrpMethod').value;
    el('rrpReportedWrap').hidden = method === 'full';
    var p = {
      price: read('rrpPrice'), basis: read('rrpBasis'), exp: read('rrpExp', true), assumed: read('rrpAssumed', true),
      method: method, payments: read('rrpPayments'), reported: method === 'full' ? 0 : read('rrpReported', true),
      unpaid: read('rrpUnpaid'), costs: read('rrpCosts', true), badDebt: read('rrpBadDebt', true),
      indefinite: el('rrpIndef').value === 'yes'
    };
    var err = el('rrpError'), msg = '';
    if (isNaN(p.price) || p.price <= 0) msg = 'Enter the selling price of the original sale.';
    else if (isNaN(p.basis) || p.basis < 0) msg = 'Enter your adjusted basis in the property when you sold it ($0 or more).';
    else if (isNaN(p.payments) || p.payments < 0) msg = 'Enter the payments you received before the repossession, including the down payment.';
    else if (isNaN(p.unpaid) || p.unpaid < 0) msg = 'Enter the unpaid balance of the buyer’s note ($0 or more).';
    else if ([p.exp, p.assumed, p.reported, p.costs, p.badDebt].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts cannot be negative.';
    else if (p.assumed > p.price) msg = 'The mortgage the buyer assumed cannot be more than the selling price.';
    else if ([p.price, p.basis, p.exp, p.assumed, p.payments, p.reported, p.unpaid, p.costs, p.badDebt].some(function (v) { return v > 1e12; })) msg = 'Amounts are too large.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); el('rrpLinesD').innerHTML = ''; el('rrpLinesE').innerHTML = ''; return; }

    var r = repossess(p);
    setText('rrpTaxable', money.format(r.d8));
    setText('rrpNewBasis', money.format(r.e7));
    setText('rrpGp', r.g.gp < 0 ? '−' + money.format(-r.g.gp) : money.format(r.g.gp));
    setText('rrpGpPct', pctFmt.format(r.g.pct));
    setText('rrpContract', money.format(r.g.cp));
    setText('rrpExpected', r.full ? money.format(r.reported) + ' (all in the year of sale)' : money.format(r.expected));
    setText('rrpBadDebtIncome', money.format(p.badDebt));

    var note;
    if (r.g.gp <= 0) {
      note = 'The original sale had no gross profit, so there is no gain to report on the repossession. Your basis in the property is the basis of the note plus your repossession costs.';
    } else if (r.d8 <= 0) {
      note = 'No gain is taxable: ' + (r.d3 <= 0 ? 'you have already reported gain equal to everything the buyer paid.' :
        'the gain you already reported plus your repossession costs use up the whole gross profit on the sale.') +
        ' Repossession costs that are not offset this way are added to the basis of the property instead.';
    } else {
      note = 'Report ' + money.format(r.d8) + ' of gain for the year you repossessed the property' +
        (p.indefinite ? ' (no limit applies because the selling price was indefinite)' :
          (r.d8 < r.d3 ? ', limited to the gross profit you expected on the sale less the gain already reported and your repossession costs' : ': the payments you have not yet taxed')) +
        '. ' + (r.full ? 'Because you did not use the installment method, it is ordinary income.' :
          'It has the same character as the gain on the original sale (capital gain or ordinary income).');
    }
    if (!r.full && r.g.gp > 0 && p.reported > 0 && Math.abs(p.reported - r.expected) > Math.max(1, 0.01 * r.expected)) {
      note += ' Check the gain already reported: under the installment method it is normally the gross profit percentage times the payments, about ' + money.format(r.expected) + '.';
    }
    if (p.badDebt > 0) note += ' The ' + money.format(p.badDebt) + ' bad debt deduction you took earlier is reported as income this year and is added to the basis of the note.';
    setText('rrpNote', note);

    rows('rrpLinesD', [
      ['1', 'Payments received before the repossession', money.format(r.d1)],
      ['2', 'Gain already reported as income', money.format(r.reported)],
      ['3', 'Gain on the repossession (line 1 minus line 2)', money.format(r.d3)],
      ['4', 'Gross profit on the original sale', money.format(r.d4)],
      ['5', 'Repossession costs', money.format(p.costs)],
      ['6', 'Line 2 plus line 5', money.format(r.d6)],
      ['7', p.indefinite ? 'Line 4 minus line 6 (limit not applied: indefinite price)' : 'Line 4 minus line 6 (limit on taxable gain)', r.d7 < 0 ? '−' + money.format(-r.d7) : money.format(r.d7)],
      ['8', 'Taxable gain on the repossession', money.format(r.d8)]
    ]);
    var eRows = [
      ['1', 'Unpaid balance of the note', money.format(r.e1)],
      ['2', 'Gross profit percentage', pctFmt.format(r.pct)],
      ['3', 'Unrealized profit (line 1 times line 2)', money.format(r.e3)],
      ['4', 'Basis in the note (line 1 minus line 3' + (p.badDebt > 0 ? ', plus bad debt recovered' : '') + ')', money.format(r.e4)],
      ['5', 'Taxable gain on the repossession', money.format(r.d8)],
      ['6', 'Repossession costs', money.format(p.costs)],
      ['7', 'Basis in the repossessed property', money.format(r.e7)]
    ];
    rows('rrpLinesE', eRows);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rrpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
